+     */
+    ActionListener<ComputeResponse> acquireCompute() {
+        return acquireAvoid().map(resp -> {
+            responseHeaders.collect();
+            if (resp != null && resp.getProfiles().isEmpty() == false) {
+                collectedProfiles.addAll(resp.getProfiles());
