-        // try to check system calls really are who they claim
-        // you never know (e.g. https://chromium.googlesource.com/chromium/src.git/+/master/sandbox/linux/seccomp-bpf/sandbox_bpf.cc#57)
-        final int bogusArg = 0xf7a46a5c;
