-                int errno2 = Native.getLastError();
-                throw new UnsupportedOperationException(
-                    "seccomp(SECCOMP_SET_MODE_FILTER): "
-                        + JNACLibrary.strerror(errno1)
-                        + ", prctl(PR_SET_SECCOMP): "
-                        + JNACLibrary.strerror(errno2)
