-                "seccomp filter installation did not really succeed. seccomp(PR_GET_SECCOMP): "
-                    + JNACLibrary.strerror(Native.getLastError())
-            );
-        }
-
-        logger.debug("Linux seccomp filter installation successful, threads: [{}]", method == 1 ? "all" : "app");
-        return method;
-    }
