-    static int init(Path tmpFile) throws Exception {
-        if (Constants.LINUX) {
-            return linuxImpl();
-        } else if (Constants.MAC_OS_X) {
-            // try to enable both mechanisms if possible
-            bsdImpl();
-            macImpl(tmpFile);
-            return 1;
-        } else if (Constants.SUN_OS) {
-            solarisImpl();
-            return 1;
-        } else if (Constants.FREE_BSD || OPENBSD) {
-            bsdImpl();
-            return 1;
-        } else if (Constants.WINDOWS) {
