+            assertFunction("ST_DISJOINT", wkt);
+            assertFunction("ST_CONTAINS", wkt);
+            // within and lines are not globally supported so we avoid it here
+            if (containsLine(geometry) == false) {
+                assertFunction("ST_WITHIN", wkt);
+            }
